#!/usr/bin/env node
// Generates the static language versions of the home page from index.html +
// assets/js/languages/translations.js, so search engines get real text in
// each language instead of text swapped in by JavaScript.
//
//   node scripts/build-i18n.mjs
//
// - assets/css/main.css    → bundle of assets/css/main.src.css (lib/css-bundle.mjs)
// - assets/img/skills.svg  → sprite of assets/img/skills/*.svg (lib/skills-sprite.mjs)
// - index.html     → rewritten in place with the English texts (idempotent)
// - es/index.html  → generated Spanish version (do not edit by hand)
// - #designs       → the block between <!-- dribbble:start/end --> in index.html
//   from scripts/data/dribbble.json (scripts/build-dribbble.mjs)
// - projects/<slug>/index.html and es/proyectos/<slug>/index.html → project
//   case-study pages from scripts/data/projects.mjs (do not edit by hand)
// - resume.html    → the block between <!-- theme:start/end --> is copied from
//   index.html (color-scheme meta + pre-paint theme script; also used by the
//   project pages)
// - sitemap.xml    → the block between <!-- projects:start/end --> is rewritten
// - llms.txt, llms-full.txt → profile for AI search engines and agents
//   (scripts/data/profile.mjs + projects.mjs + scripts/cv/data.mjs)
// - checks that every page preloads (modulepreload) exactly the modules it
//   imports up front (lib/module-preloads.mjs)
//
// This file only orchestrates: each step lives in scripts/lib/ (the i18n markup
// conventions, data-i18n and data-i18n-attr, are described in lib/render.mjs).

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import cv from './cv/data.mjs';
import profile from './data/profile.mjs';
import projects from './data/projects.mjs';
import { bundleCss } from './lib/css-bundle.mjs';
import { injectDesigns } from './lib/designs-section.mjs';
import { llmsFullTxt, llmsTxt } from './lib/llms.mjs';
import { checkModulePreloads } from './lib/module-preloads.mjs';
import { adaptHeader, homeChrome, projectPage } from './lib/project-page.mjs';
import { failOnMissing, render } from './lib/render.mjs';
import { LANGS, PROJECT_DIRS, ROOT, fail, projectPath } from './lib/site.mjs';
import { withProjectEntries } from './lib/sitemap.mjs';
import { buildSkillsSprite, setSpriteVersion, unknownSpriteIds } from './lib/skills-sprite.mjs';
import { extractThemeHead, injectThemeHead, stripThemeMarkers } from './lib/theme-head.mjs';

const file = (relative) => path.join(ROOT, relative);
const read = (relative) => fs.readFileSync(file(relative), 'utf8');
const write = (relative, content) => {
  fs.mkdirSync(path.dirname(file(relative)), { recursive: true });
  fs.writeFileSync(file(relative), content);
};
const generatedFrom = (source) => `<!-- GENERATED by scripts/build-i18n.mjs from ${source} — do not edit -->`;
const withBanner = (html, source) => html.replace('<!DOCTYPE html>', `<!DOCTYPE html>\n${generatedFrom(source)}`);

const homeSource = read('index.html');

// Checked before anything is written: failing later would leave the home pages
// regenerated while resume.html and the project pages keep the old theme block
extractThemeHead(homeSource, 'index.html');
extractThemeHead(read('resume.html'), 'resume.html');

buildCss();
const home = buildSprite(homeSource);
const en = buildHome(home);
const themeHead = syncThemeHead(en);
buildProjectPages(en, themeHead);
buildSitemap();
console.log(`✔ ${projects.length * LANGS.length} project pages and sitemap.xml generated`);
buildLlms();

function buildCss() {
  write('assets/css/main.css', bundleCss(file('assets/css')));
  console.log('✔ assets/css/main.css bundled');
}

/**
 * Writes the skills sprite and index.html (`html`) pointing to its new version;
 * returns that page
 */
function buildSprite(html) {
  const { sprite, ids, version } = buildSkillsSprite(file('assets/img/skills'));
  write('assets/img/skills.svg', sprite);

  // Written right away, so index.html has the new version even if a later step
  // fails; the next steps get the page in memory instead of reading it back
  const versioned = setSpriteVersion(html, version);
  write('index.html', versioned);

  // Every reference in the home page must exist in the sprite
  const unknown = unknownSpriteIds(versioned, ids);
  if (unknown.length) fail(`index.html uses icons that are not in skills.svg: ${unknown.join(', ')}`);
  console.log(`✔ assets/img/skills.svg (${ids.size} icons)`);
  return versioned;
}

/** Writes index.html (en) and es/index.html; returns the English page */
function buildHome(html) {
  // "Designs" section (Dribbble shots, scripts/build-dribbble.mjs)
  const source = injectDesigns(html, file('scripts/data/dribbble.json'));
  const en = render(source, 'en');
  const es = render(source, 'es');
  failOnMissing();

  checkModulePreloads(en, 'index.html');
  write('index.html', en);
  // The theme markers stay in index.html only: they say "edit this block here"
  write('es/index.html', withBanner(stripThemeMarkers(es), 'index.html'));
  console.log('✔ index.html (en) and es/index.html (es) generated');
  return en;
}

/**
 * Pre-paint theme block (<!-- theme:start/end -->): index.html is the single
 * source; resume.html gets a copy in place. Returns the block for the project pages.
 */
function syncThemeHead(homeHtml) {
  const block = extractThemeHead(homeHtml, 'index.html');
  const resume = injectThemeHead(read('resume.html'), block, 'resume.html');
  checkModulePreloads(resume, 'resume.html');
  write('resume.html', resume);
  return block;
}

/** Project case-study pages, with the header, footer and theme block of the home page */
function buildProjectPages(homeHtml, themeHead) {
  const { header, footer } = homeChrome(homeHtml);
  for (const dir of Object.values(PROJECT_DIRS)) {
    fs.rmSync(file(dir), { recursive: true, force: true }); // drop renamed/removed slugs
  }

  projects.forEach((project, i) => {
    const prev = projects[(i - 1 + projects.length) % projects.length];
    const next = projects[(i + 1) % projects.length];
    for (const lang of LANGS) {
      const page = projectPage({ project, lang, prev, next, header: adaptHeader(header, lang), footer, themeHead });
      checkModulePreloads(page, 'scripts/lib/project-page.mjs');
      write(
        path.join(projectPath(project, lang), 'index.html'),
        withBanner(render(page, lang), 'scripts/data/projects.mjs'),
      );
    }
  });
  failOnMissing();
}

/**
 * YYYY-MM-DD of the last commit that changed `files`: a stable date, so a build
 * on another day doesn't rewrite the sitemap when nothing changed. Today when
 * they have uncommitted changes (they are being edited) or git isn't available.
 */
function lastChanged(files) {
  // Local date, like git's %cs (the commit's own time zone): toISOString() is
  // UTC, a day ahead in the evening west of Greenwich, so an edit built then
  // and committed the same evening would get two different dates
  const now = new Date();
  const pad = (n) => String(n).padStart(2, '0');
  const today = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
  const git = (...args) =>
    execFileSync('git', ['-C', ROOT, ...args, '--', ...files], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  try {
    if (git('status', '--porcelain')) return today;
    return git('log', '-1', '--format=%cs') || today;
  } catch {
    return today;
  }
}

/**
 * Sitemap entries for the project pages (with hreflang alternates). Their
 * <lastmod> is the last change to the files the pages are made from.
 */
function buildSitemap() {
  const lastmod = lastChanged(['scripts/data/projects.mjs', 'scripts/lib/project-page.mjs']);
  write('sitemap.xml', withProjectEntries(read('sitemap.xml'), projects, lastmod));
}

/** llms.txt / llms-full.txt (AI search engines and agents) */
function buildLlms() {
  const data = { profile, projects, cv };
  write('llms.txt', llmsTxt(data));
  write('llms-full.txt', llmsFullTxt(data));
  console.log('✔ llms.txt and llms-full.txt generated');
}
